UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"tall ascetic adult deity with trident, matted hair and balanced stillness/dance tension","appearance":{"face":["mature adult face with calm inward gaze and visible third eye"],"body":["lean powerful adult yogic build"]},"costumeLanguage":["ascetic dhoti and sacred ornaments with restrained tiger-skin motif"],"paletteCues":["ash blue","charcoal","copper"],"temperament":["transcendent","austere","formidable"],"mythologicalFacts":["major deity associated with destruction, transformation, yoga and dance"],"originalDesignChoices":["Keep sacred attributes legible without copying calendar-art or film designs."],"avoid":["generic fantasy barbarian","specific modern franchise likeness"],"canonicalPrompt":"Depict Shiva as an original MythCanvas interpretation. Preserve the trident, third eye, crescent moon and matted hair. Use restrained sacred ascetic garments and ornaments with a powerful adult yogic presence balancing stillness and cosmic transformation."}') WHERE id='character-shiva';
